/// <summary>
///    The <c>UnitOfMeasureLookup</c> class provides the methods to perform lookup on the
///    <c>EcoResProduct</c> table, controls the <c>EcoResProductLookup</c> lookup form behavior, and
///    handles form events.
/// </summary>
class GUPCustTradingPartnerCodeLookup
{
    public  boolean returnRefRecID = false;

}

Method.Source:
    final public boolean parmreturnRefRecID(boolean _returnRefRecID = returnRefRecID)
    {
        returnRefRecID = _returnRefRecID;

        return returnRefRecID;
    }

    public CustTradingPartnerCode performLookup(FormStringControl _formStringControl)
    {
        Args args = new Args();
        args.name(formStr(GUPCustTradingPartnerCodeLookup));
        args.caller(this);

        args.parmObject(this);
        args.lookupField(fieldNum(CustTradingPartnerCode, RecId));
        args.lookupValue(_formStringControl.valueStr());

        FormRun formRun = classfactory.formRunClass(args);
        formRun.init();

        _formStringControl.performFormLookup(formRun);
        CustTradingPartnerCode custTradingPartnerCode = formRun.selectRecordModeSelectedRecord() as CustTradingPartnerCode;

        return custTradingPartnerCode;
    }

public static GUPCustTradingPartnerCodeLookup construct(boolean _returnRefRecID)
{
    return new GUPCustTradingPartnerCodeLookup(_returnRefRecID);
}
